class Solution {
public:
    int maxScore(int n, int k, vector<vector<int>>& stayScore, vector<vector<int>>& travelScore) {
        vector<int> dp(n, 0);
        for (int day = 0; day < k; ++day) {
            vector<int> new_dp(n, 0);
            for (int curr = 0; curr < n; ++curr) {
                new_dp[curr] = max(new_dp[curr], dp[curr] + stayScore[day][curr]);
                for (int prev = 0; prev < n; ++prev) {
                    if (prev != curr) {
                        new_dp[curr] = max(new_dp[curr], dp[prev] + travelScore[prev][curr]);
                    }
                }
            }
            dp = std::move(new_dp);
        }
        return *max_element(dp.begin(), dp.end());
    }
};

class Solution {
    public int maxScore(int n, int k, int[][] stayScore, int[][] travelScore) {
        int[] dp = new int[n];
        for (int day = 0; day < k; day++) {
            int[] newDp = new int[n];
            for (int curr = 0; curr < n; curr++) {
                newDp[curr] = Math.max(newDp[curr], dp[curr] + stayScore[day][curr]);
                for (int prev = 0; prev < n; prev++) {
                    if (prev != curr) {
                        newDp[curr] = Math.max(newDp[curr], dp[prev] + travelScore[prev][curr]);
                    }
                }
            }
            dp = newDp;
        }
        int maxVal = 0;
        for (int v : dp) maxVal = Math.max(maxVal, v);
        return maxVal;
    }
}

var maxScore = function(n, k, stayScore, travelScore) {
    let dp = new Array(n).fill(0);
    for (let day = 0; day < k; day++) {
        const newDp = new Array(n).fill(0);
        for (let curr = 0; curr < n; curr++) {
            newDp[curr] = Math.max(newDp[curr], dp[curr] + stayScore[day][curr]);
            for (let prev = 0; prev < n; prev++) {
                if (prev !== curr) {
                    newDp[curr] = Math.max(newDp[curr], dp[prev] + travelScore[prev][curr]);
                }
            }
        }
        dp = newDp;
    }
    return Math.max(...dp);
};
